<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kelola Pembayaran | Asrama Putri Junjung Buyah Kukar YK</title>
    <style>
        :root { --ink: #171717; --muted: #737373; --line: #e5e5e5; --soft: #fafafa; --yellow: #ffe51f; --green: #078455; --red: #b42318; }
        * { box-sizing: border-box; } body { margin: 0; color: var(--ink); background: #fff; font-family: Inter, system-ui, sans-serif; } a { color: inherit; text-decoration: none; } button, input, select { font: inherit; }
        .topbar { height: 61px; display: flex; align-items: center; justify-content: space-between; gap: 24px; padding: 0 28px; border-bottom: 1px solid var(--line); } .brand { display: flex; align-items: center; gap: 10px; color: var(--muted); font-size: 14px; white-space: nowrap; } .brand img { width: 29px; height: 29px; border-radius: 50%; object-fit: cover; } .brand strong { color: var(--ink); } .top-search, .search { display: flex; align-items: center; gap: 10px; border: 1px solid var(--line); border-radius: 8px; color: #999; background: #fff; } .top-search { width: min(385px, 34vw); padding: 9px 12px; } .top-search input, .search input { width: 100%; border: 0; outline: 0; color: var(--ink); background: transparent; font-size: 13px; } .shortcut { padding: 3px 7px; border: 1px solid var(--line); border-radius: 4px; font-size: 10px; } .top-actions { display: flex; gap: 8px; } .icon-button { width: 39px; height: 39px; border: 1px solid var(--line); border-radius: 8px; color: var(--muted); background: #fff; }
        main { max-width: 1650px; margin: auto; padding: 29px 24px 60px; } h1 { margin: 0; font-size: 25px; letter-spacing: -.04em; } .intro { margin: 6px 0 24px; color: var(--muted); font-size: 14px; } .page-head { display: flex; align-items: end; justify-content: space-between; gap: 24px; margin-bottom: 24px; } .head-actions { display: flex; gap: 8px; } .button { padding: 11px 15px; border: 1px solid var(--line); border-radius: 8px; color: var(--ink); background: #fff; font-size: 12px; font-weight: 800; cursor: pointer; } .button.primary { border-color: var(--ink); color: #fff; background: var(--ink); }
        .notice, .errors { margin-bottom: 18px; padding: 12px 15px; border-radius: 8px; font-size: 13px; } .notice { color: #166534; background: #ecfdf5; } .errors { color: var(--red); background: #fff1f1; } .errors ul { margin: 0; padding-left: 18px; }
        .add-panel { display: none; margin-bottom: 20px; padding: 22px; border: 1px solid var(--line); border-radius: 11px; background: var(--soft); } .add-panel.open { display: block; } .add-panel h2 { margin: 0 0 18px; font-size: 17px; } .add-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; } .field { display: grid; gap: 7px; } .field label { font-size: 11px; font-weight: 800; } .field input, .field select { width: 100%; padding: 10px; border: 1px solid #ddd; border-radius: 8px; outline: 0; background: #fff; font-size: 13px; } .field small { color: var(--muted); font-size: 11px; } .form-actions { display: flex; justify-content: end; margin-top: 16px; }
        .panel { overflow: hidden; border: 1px solid var(--line); border-radius: 9px; } .panel-head { display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 16px 20px; border-bottom: 1px solid var(--line); } .tabs { display: flex; gap: 4px; padding: 4px; border: 1px solid var(--line); border-radius: 7px; } .tab { padding: 9px 15px; border: 0; border-radius: 5px; color: var(--muted); background: transparent; font-size: 13px; cursor: pointer; } .tab.active { color: #fff; background: var(--ink); font-weight: 800; } .search { width: 290px; padding: 10px 12px; } .count { padding: 0 20px 15px; color: var(--muted); font-size: 12px; text-align: right; }
        .table-wrap { overflow-x: auto; } table { width: 100%; min-width: 1100px; border-collapse: collapse; } th, td { padding: 14px 20px; border-bottom: 1px solid #eeeeee; text-align: left; vertical-align: middle; } th { color: #626262; background: #fcfcfc; font-size: 10px; letter-spacing: .13em; text-transform: uppercase; white-space: nowrap; } td { color: #555; font-size: 13px; } tbody tr:hover { background: #fffef3; } tbody tr:last-child td { border-bottom: 0; } .number { width: 55px; color: #888; text-align: center; } .resident { min-width: 180px; color: var(--ink); font-weight: 700; } .resident small, .period small { display: block; margin-top: 4px; color: #999; font-size: 11px; font-weight: 400; } .period { white-space: nowrap; } .amount { color: var(--ink); font-weight: 800; white-space: nowrap; } .method { display: inline-flex; padding: 5px 10px; border: 1px solid #add4ff; border-radius: 99px; color: #075fd8; background: #f0f7ff; font-size: 10px; font-weight: 800; text-transform: uppercase; } .method.cash { border-color: #ffd76a; color: #ad6500; background: #fffaf0; } .status { display: inline-flex; padding: 5px 10px; border-radius: 99px; color: #9a6500; background: #fff8da; font-size: 10px; font-weight: 800; text-transform: uppercase; white-space: nowrap; } .status.lunas { color: var(--green); background: #eafaf2; } .status.ditolak { color: var(--red); background: #fff0f0; } .proof { color: #075fd8; font-size: 12px; font-weight: 700; } .actions { display: flex; gap: 7px; } .action { padding: 8px 10px; border: 1px solid var(--line); border-radius: 7px; background: #fff; font-size: 11px; font-weight: 800; cursor: pointer; } .action.accept { border-color: #9ae6c8; color: var(--green); } .action.reject { border-color: #ffc5c5; color: var(--red); } .action:hover { background: var(--soft); } .empty { padding: 48px; color: var(--muted); text-align: center; } .pagination { padding: 15px 20px; border-top: 1px solid var(--line); }
        @media (max-width: 900px) { .top-search { display: none; } .page-head { align-items: flex-start; flex-direction: column; } .head-actions { width: 100%; } .head-actions .button { flex: 1; text-align: center; } .add-grid { grid-template-columns: repeat(2, 1fr); } .panel-head { align-items: flex-start; flex-direction: column; } .search { width: 100%; } } @media (max-width: 560px) { .topbar { padding: 0 16px; } main { padding: 24px 14px 45px; } .add-grid { grid-template-columns: 1fr; } .tabs { width: 100%; } .tab { flex: 1; } }
        html[data-theme="dark"] body { color: #f4f4f4; background: #111; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .panel, html[data-theme="dark"] .add-panel { background: #191919; border-color: #333; } html[data-theme="dark"] .top-search, html[data-theme="dark"] .search, html[data-theme="dark"] .icon-button, html[data-theme="dark"] .button, html[data-theme="dark"] .action { color: #eee; background: #191919; border-color: #444; } html[data-theme="dark"] input, html[data-theme="dark"] select { color: #eee; background: #222; border-color: #444; } html[data-theme="dark"] th { background: #202020; } html[data-theme="dark"] td, html[data-theme="dark"] th { border-color: #333; } html[data-theme="dark"] .brand strong, html[data-theme="dark"] h1, html[data-theme="dark"] h2 { color: #fff; }
        :root { --ink: #17201d; --muted: #68736f; --line: #e5e9e6; --soft: #f7f9f6; }
        body { background: radial-gradient(circle at 90% 0, #e9f7c8 0, transparent 28%), #f4f7f3; } .topbar { position: sticky; top: 0; z-index: 4; height: 68px; padding: 0 34px; background: rgba(255,255,255,.9); backdrop-filter: blur(16px); } main { max-width: 1560px; padding: 42px 34px 70px; } .panel { border-radius: 16px; box-shadow: 0 14px 40px rgba(23,32,29,.07); } .button, .action { border-radius: 10px; } th { background: #fbfcfa; color: #68736f; } td { color: #34413c; } tbody tr:hover { background: #f7faed; }
        html[data-theme="dark"] body { color: #f3f7f4; background: #101412; } html[data-theme="dark"] .topbar, html[data-theme="dark"] .panel, html[data-theme="dark"] .add-panel { background: #1a211e; border-color: #35413b; } html[data-theme="dark"] th { color: #dce7e0; background: #26312b; border-color: #405047; } html[data-theme="dark"] td { color: #d7e1da; border-color: #35413b; } html[data-theme="dark"] tbody tr:hover { background: #29362d; } html[data-theme="dark"] h1, html[data-theme="dark"] h2, html[data-theme="dark"] .brand strong { color: #f3f7f4; } html[data-theme="dark"] input, html[data-theme="dark"] select, html[data-theme="dark"] .search, html[data-theme="dark"] .action { color: #f3f7f4; background: #202923; border-color: #4a5a50; }
        .account-box { margin-top: 12px; padding: 11px 14px; border: 1px solid #dfe7d9; border-radius: 10px; color: #526158; background: #f7faf0; font-size: 12px; }
        #settings-panel { display: none; } #settings-panel.open { display: block; }
        html[data-theme="dark"] .account-box { color: #d7e1da; background: #202923; border-color: #4a5a50; }
    </style>
    <script>document.documentElement.dataset.theme = localStorage.getItem('admin-theme') || (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');</script>
</head>
<body>
    <header class="topbar"><a class="brand" href="{{ route('admin.dashboard') }}"><img src="{{ asset('images/logo-siap-kukar.png') }}" alt="Logo Asrama Putri Junjung Buyah Kukar YK"><span>Asrama Putri Junjung Buyah Kukar YK</span><span>›</span><strong>Kelola Pembayaran</strong></a><div class="top-search"><span>⌕</span><input id="global-search" placeholder="Cari penghuni, periode, pembayaran..."><span class="shortcut">Ctrl K</span></div><div class="top-actions"><button class="icon-button" type="button" aria-label="Notifikasi">♧</button><button class="icon-button" type="button" id="theme-toggle" aria-label="Ganti mode warna">☼</button></div></header>
    <main>
        <div class="page-head"><div><h1>Kelola Pembayaran</h1><p class="intro">Kelola uang registrasi, iuran bulanan, dan verifikasi transaksi penghuni.</p><div class="account-box">Pembayaran ke: <strong>{{ $settings['bank'] ?? '-' }}</strong> · <strong>{{ $settings['nomor_rekening'] ?? '-' }}</strong> · a.n. <strong>{{ $settings['atas_nama'] ?? '-' }}</strong></div></div><div class="head-actions"><a class="button" href="{{ route('admin.dashboard') }}">Dashboard</a><button class="button" id="settings-button" type="button">Pengaturan</button><button class="button primary" id="add-button" type="button">＋ Tambah Pembayaran</button></div></div>
        @if (session('success')) <div class="notice">{{ session('success') }}</div> @endif @if ($errors->any()) <div class="errors"><ul>@foreach ($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div> @endif
        <section class="add-panel" id="settings-panel"><h2>Pengaturan Pembayaran</h2><form method="POST" action="{{ route('admin.pembayaran.settings') }}">@csrf<div class="add-grid"><div class="field"><label>Nominal Registrasi</label><input type="number" name="nominal_registrasi" value="{{ $settings['nominal_registrasi'] ?? 0 }}" required></div><div class="field"><label>Nominal Iuran Bulanan</label><input type="number" name="nominal_iuran_bulanan" value="{{ $settings['nominal_iuran_bulanan'] ?? 0 }}" required></div><div class="field"><label>Bank</label><input name="bank" value="{{ $settings['bank'] ?? '' }}" required></div><div class="field"><label>Nomor Rekening</label><input name="nomor_rekening" value="{{ $settings['nomor_rekening'] ?? '' }}" required></div><div class="field"><label>Atas Nama</label><input name="atas_nama" value="{{ $settings['atas_nama'] ?? '' }}" required></div></div><div class="form-actions"><button class="button primary" type="submit">Simpan Pengaturan</button></div></form></section><section class="add-panel" id="add-panel"><h2>Tambah Pembayaran</h2><form method="POST" action="{{ route('admin.pembayaran.store') }}" enctype="multipart/form-data">@csrf<div class="add-grid"><div class="field"><label>Penghuni</label><select name="user_id" required><option value="">Pilih Penghuni</option>@foreach ($penghunis as $penghuni)<option value="{{ $penghuni->id }}">{{ $penghuni->name }}</option>@endforeach</select></div><div class="field"><label>Jenis Pembayaran</label><select name="jenis_pembayaran" required><option value="iuran_bulanan">Iuran Bulanan</option><option value="registrasi">Uang Registrasi</option></select></div><div class="field"><label>Bulan Tagihan</label><select name="bulan_tagihan" required>@foreach (range(1, 12) as $bulan)<option value="{{ $bulan }}">{{ $bulan }}</option>@endforeach</select></div><div class="field"><label>Tahun Tagihan</label><input type="number" name="tahun_tagihan" value="{{ date('Y') }}" min="2020" max="2100" required></div><div class="field"><label>Jumlah Bayar</label><input type="number" name="jumlah_bayar" min="0" step="0.01" required></div><div class="field"><label>Metode Pembayaran</label><select name="metode_pembayaran" required><option value="cash">Cash</option><option value="transfer">Transfer</option></select></div><div class="field"><label>Bukti Transfer</label><input type="file" name="bukti_transfer" accept=".pdf,.jpg,.jpeg,.png"><small>Opsional · PDF/JPG/PNG, maksimal 3 MB.</small></div></div><div class="form-actions"><button class="button primary" type="submit">Simpan Pembayaran</button></div></form></section>
        <section class="panel"><div class="panel-head"><div class="tabs"><button class="tab active" type="button" data-filter="all">Semua</button><button class="tab" type="button" data-filter="menunggu_verifikasi">Menunggu</button><button class="tab" type="button" data-filter="lunas">Lunas</button><button class="tab" type="button" data-filter="ditolak">Ditolak</button></div><div class="search"><span>⌕</span><input id="payment-search" placeholder="Cari penghuni atau periode..."></div></div><div class="count">Menampilkan <span id="payment-count">{{ $pembayarans->count() }}</span> pembayaran.</div><div class="table-wrap"><table><thead><tr><th class="number">No</th><th>Penghuni</th><th>Jenis</th><th>Periode</th><th>Jumlah</th><th>Metode</th><th>Bukti Transfer</th><th>Status</th><th>Aksi</th></tr></thead><tbody id="payment-list">@forelse ($pembayarans as $index => $pembayaran)<tr data-status="{{ $pembayaran->status_pembayaran }}" data-search="{{ strtolower(($pembayaran->user?->name ?? '').' '.$pembayaran->bulan_tagihan.'/'.$pembayaran->tahun_tagihan) }}"><td class="number">{{ $pembayarans->firstItem() + $index }}</td><td class="resident">{{ $pembayaran->user?->name ?? '-' }}<small>{{ $pembayaran->user?->email ?? '-' }}</small></td><td><span class="method">{{ $pembayaran->jenis_pembayaran === 'registrasi' ? 'Registrasi' : 'Iuran Bulanan' }}</span></td><td class="period">{{ $pembayaran->bulan_tagihan }}/{{ $pembayaran->tahun_tagihan }}<small>Tagihan Asrama</small></td><td class="amount">Rp {{ number_format($pembayaran->jumlah_bayar, 0, ',', '.') }}</td><td><span class="method {{ $pembayaran->metode_pembayaran === 'cash' ? 'cash' : '' }}">{{ $pembayaran->metode_pembayaran }}</span></td><td>@if ($pembayaran->bukti_transfer)<a class="proof" href="{{ asset('storage/'.$pembayaran->bukti_transfer) }}" target="_blank" rel="noopener">Lihat Bukti</a>@else - @endif</td><td><span class="status {{ $pembayaran->status_pembayaran }}">{{ str_replace('_', ' ', $pembayaran->status_pembayaran) }}</span></td><td>@if ($pembayaran->status_pembayaran === 'menunggu_verifikasi')<div class="actions"><form method="POST" action="{{ route('admin.pembayaran.update', $pembayaran) }}" onsubmit="return confirm('Terima pembayaran ini?')">@csrf @method('PATCH')<input type="hidden" name="status_pembayaran" value="lunas"><button class="action accept" type="submit">Terima</button></form><form method="POST" action="{{ route('admin.pembayaran.update', $pembayaran) }}" onsubmit="return confirm('Tolak pembayaran ini?')">@csrf @method('PATCH')<input type="hidden" name="status_pembayaran" value="ditolak"><button class="action reject" type="submit">Tolak</button></form></div>@else - @endif @if($pembayaran->status_pembayaran === 'lunas')<a class="proof" href="{{ route('admin.pembayaran.receipt', $pembayaran) }}">Kuitansi PDF</a>@endif</td></tr>@empty<tr><td colspan="9" class="empty">Belum ada data pembayaran.</td></tr>@endforelse</tbody></table></div>@if ($pembayarans->hasPages())<div class="pagination">{{ $pembayarans->links() }}</div>@endif</section>
    </main>
    <script>
        const addPanel = document.querySelector('#add-panel'); document.querySelector('#add-button').addEventListener('click', () => addPanel.classList.toggle('open')); const settingsPanel = document.querySelector('#settings-panel'); document.querySelector('#settings-button').addEventListener('click', () => settingsPanel.classList.toggle('open'));
        const search = document.querySelector('#payment-search'); const globalSearch = document.querySelector('#global-search'); const rows = [...document.querySelectorAll('#payment-list tr[data-search]')]; const tabs = [...document.querySelectorAll('[data-filter]')]; let filter = 'all';
        const applyFilter = () => { const query = search.value.toLowerCase().trim(); let visible = 0; rows.forEach((row) => { const show = (filter === 'all' || row.dataset.status === filter) && row.dataset.search.includes(query); row.hidden = !show; if (show) visible += 1; }); document.querySelector('#payment-count').textContent = visible; };
        search.addEventListener('input', applyFilter); globalSearch.addEventListener('input', () => { search.value = globalSearch.value; applyFilter(); }); tabs.forEach((tab) => tab.addEventListener('click', () => { tabs.forEach((item) => item.classList.remove('active')); tab.classList.add('active'); filter = tab.dataset.filter; applyFilter(); })); document.addEventListener('keydown', (event) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); globalSearch.focus(); } });
    </script>
<script>const themeToggle=document.querySelector('#theme-toggle');const setTheme=()=>{const dark=document.documentElement.dataset.theme==='dark';themeToggle.textContent=dark?'☀':'☾';themeToggle.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('admin-theme',next);themeToggle.textContent=next==='dark'?'☀':'☾';};};setTheme();</script></body>
</html>
